sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {
 // If notification is "Draft workplace inspection report reminder"

	var instanceName = gs.getProperty('instance_name');
    var url = "https://" + instanceName + ".service-now.com/" ;

    if (email_action.name == "Draft workplace inspection report reminder" || email_action.name == "HoC - OHSM SC OHS Advisor resolution") {
     url = url + "nav_to.do?uri=x_hccc_hoc_ohs_investigation_case.do?sys_id=" + current.sys_id.toString();

        template.print("<a title=" + 'link' + " href='" + url + "'" + "target=" + '_blank' + " rel=" + 'noopener' + ">link</a>");
    } 
	else {
        url = url+ "services?id=hoc_hrm_ticket_page&table=x_hccc_hoc_ohs_investigation_case&sys_id=" + current.sys_id.toString();

        template.print("<a title=" + 'link' + " href='" + url + "'" + "target=" + '_blank' + " rel=" + 'noopener' + ">lien</a>");
    }



})(current, template, email, email_action, event);
